func openScanner() async -> Bool {
  switch AVCaptureDevice.authorizationStatus(for: .video) {
  case .authorized:
    return true
  case .notDetermined:
    // The only moment iOS will ever ask. Show your own explanation before this line.
    return await AVCaptureDevice.requestAccess(for: .video)
  case .denied, .restricted:
    // There is no second prompt — Settings is the only route back.
    _ = await UIApplication.shared.open(URL(string: UIApplication.openSettingsURLString)!)
    return false
  @unknown default:
    return false
  }
}

