// One feature, one permission, asked at the tap that starts the feature.
@Composable
fun ExportToCalendarButton(vm: ExportViewModel) {
  val ctx = LocalContext.current
  var showPrimer by remember { mutableStateOf(false) }

  val launcher = rememberLauncherForActivityResult(
    ActivityResultContracts.RequestPermission()
  ) { granted -> if (granted) vm.export() else vm.offerIcsDownloadInstead() }

  Button(onClick = {
    if (ctx.hasPermission(Manifest.permission.WRITE_CALENDAR)) vm.export()
    else showPrimer = true          // your screen first, the system dialog second
  }) { Text("Add to calendar") }

  if (showPrimer) {
    AlertDialog(
      // Dismissing costs nothing and can be shown again tomorrow.
      onDismissRequest = { showPrimer = false },
      title = { Text("Put your bookings in your calendar") },
      text = { Text("We add one event per booking. We never read your existing events.") },
      confirmButton = {
        TextButton(onClick = {
          showPrimer = false
          launcher.launch(Manifest.permission.WRITE_CALENDAR)   // spent once, for good
        }) { Text("Continue") }
      },
      dismissButton = { TextButton(onClick = { showPrimer = false }) { Text("Not now") } }
    )
  }
}

