// Foreground first. Coarse and fine go in one request, because the dialog may return coarse only.
private val foreground = registerForActivityResult(
  ActivityResultContracts.RequestMultiplePermissions()
) { result ->
  when {
    result[Manifest.permission.ACCESS_FINE_LOCATION] == true ->
      startTracking(Priority.PRIORITY_HIGH_ACCURACY)
    result[Manifest.permission.ACCESS_COARSE_LOCATION] == true ->
      startTracking(Priority.PRIORITY_BALANCED_POWER_ACCURACY)   // approximate still works
    else -> showDeniedState()
  }
}

// Background is a separate, later request — never bundled with the first one.
private val background = registerForActivityResult(
  ActivityResultContracts.RequestPermission()
) { granted -> if (!granted) offerForegroundOnlyMode() }

fun onDeliveryAccepted() {
  if (!hasForegroundLocation()) {
    foreground.launch(arrayOf(
      Manifest.permission.ACCESS_FINE_LOCATION,
      Manifest.permission.ACCESS_COARSE_LOCATION))
    return
  }
  // From Android 11 this opens your app's location settings page: the activity stops and
  // restarts, so the real answer arrives in onResume, not in the callback above.
  background.launch(Manifest.permission.ACCESS_BACKGROUND_LOCATION)
}

