final class VoiceNoteRecorder {
  private let session = AVAudioSession.sharedInstance()
  private var recorder: AVAudioRecorder?

  func start(to url: URL, settings: [String: Any]) throws {
    try session.setCategory(.record, mode: .default)
    try session.setActive(true)              // the orange dot lights up on this line
    recorder = try AVAudioRecorder(url: url, settings: settings)
    recorder?.record()
  }

  func stop() {
    recorder?.stop()
    recorder = nil
    // ❌ stopping here leaves the session active: the dot stays lit, Control Center keeps
    // naming your app, and every other app stays ducked.
    try? session.setActive(false, options: .notifyOthersOnDeactivation)
  }
}

