// The prompt appears only while the status is .notDetermined. After that this is a plain read.
func askForNotifications() async -> Bool {
  let center = UNUserNotificationCenter.current()
  let settings = await center.notificationSettings()

  switch settings.authorizationStatus {
  case .notDetermined:
    let granted = (try? await center.requestAuthorization(options: [.alert, .badge, .sound]))
      ?? false
    if granted { await UIApplication.shared.registerForRemoteNotifications() }
    return granted

  case .denied:
    // No second prompt exists. Land on the notification page, not the settings root.
    let url = URL(string: UIApplication.openNotificationSettingsURLString)!   // iOS 16+
    _ = await UIApplication.shared.open(url)
    return false

  default:
    // .authorized or .provisional — the status alone is not the whole story
    return settings.alertSetting == .enabled
  }
}

// Provisional: no dialog at all. Delivery is quiet, and the first notification carries the
// choice — deliver prominently, keep quiet, or turn off.
func enrolQuietly() async {
  _ = try? await UNUserNotificationCenter.current()
    .requestAuthorization(options: [.alert, .sound, .badge, .provisional])
}

