@MainActor
func requestTrackingWhenReady() async -> ATTrackingManager.AuthorizationStatus {
  // Wait until the app is really foregrounded, otherwise the system drops the request
  while UIApplication.shared.applicationState != .active {
    try? await Task.sleep(for: .milliseconds(100))
  }
  return await ATTrackingManager.requestTrackingAuthorization()
}

func advertisingIdentifier() -> UUID? {
  guard ATTrackingManager.trackingAuthorizationStatus == .authorized else { return nil }
  let idfa = ASIdentifierManager.shared().advertisingIdentifier
  // Unauthorised it is 00000000-0000-0000-0000-000000000000 — never a usable key
  return idfa.uuidString.hasPrefix("00000000") ? nil : idfa
}

func startAdStack() async {
  let status = await requestTrackingWhenReady()
  AdSDK.configure(idfa: advertisingIdentifier())     // nil is the expected case
  // .denied and .restricted are not failures: the campaign still measures through
  // SKAdNetwork / AdAttributionKit postbacks, which need no per-user identifier.
  if status != .authorized { Analytics.setPersonalisedAds(false) }
}

