class ConsentGate(private val app: Application, private val store: ConsentStore) {

  // Called before any SDK is allowed to speak, including on a cold start
  fun applyDenied() = FirebaseAnalytics.getInstance(app).setConsent(
    mapOf(
      ConsentType.ANALYTICS_STORAGE to ConsentStatus.DENIED,
      ConsentType.AD_STORAGE to ConsentStatus.DENIED,
      ConsentType.AD_USER_DATA to ConsentStatus.DENIED,
      ConsentType.AD_PERSONALIZATION to ConsentStatus.DENIED,
    )
  )

  fun onAnswer(c: Consent) {
    store.record(c, at = System.currentTimeMillis(), noticeVersion = "2026-04-eu")
    val analytics = FirebaseAnalytics.getInstance(app)
    analytics.setConsent(
      mapOf(
        ConsentType.ANALYTICS_STORAGE to c.analytics.asStatus(),
        ConsentType.AD_STORAGE to c.ads.asStatus(),
        ConsentType.AD_USER_DATA to c.ads.asStatus(),
        ConsentType.AD_PERSONALIZATION to c.ads.asStatus(),
      )
    )
    analytics.setAnalyticsCollectionEnabled(c.analytics)
    FirebaseCrashlytics.getInstance().isCrashlyticsCollectionEnabled = c.crash

    if (!c.analytics) {
      eventQueue.clear()          // whatever was buffered on disk must never flush
      analytics.resetAnalyticsData()   // new app-instance id, old one unusable
    }
  }
}

// build.gradle.kts (:app) — fail the build when a dependency smuggles a permission in
import com.android.build.api.artifact.SingleArtifact

abstract class CheckPermissions : DefaultTask() {
    @get:InputFile abstract val mergedManifest: RegularFileProperty
    @get:InputFile abstract val allowList: RegularFileProperty

    @TaskAction
    fun check() {
        val declared = Regex("uses-permission[^>]*android:name=\"([^\"]+)\"")
            .findAll(mergedManifest.get().asFile.readText())
            .map { it.groupValues[1] }
            .toSet()
        val allowed = allowList.get().asFile.readLines()
            .filter { it.isNotBlank() && !it.startsWith("#") }
            .toSet()
        val added = declared - allowed
        // The point is the review, not the list: someone has to say why it is there
        check(added.isEmpty()) {
            "a dependency added ${added.joinToString()} — allow-list it or remove it"
        }
    }
}

androidComponents.onVariants { variant ->
    val task = tasks.register<CheckPermissions>("check${variant.name}Permissions") {
        mergedManifest.set(variant.artifacts.get(SingleArtifact.MERGED_MANIFEST))
        allowList.set(layout.projectDirectory.file("permissions-allowlist.txt"))
    }
    tasks.named("assemble${variant.name.replaceFirstChar { it.uppercase() }}") {
        dependsOn(task)
    }
}

