func deleteAccount() async throws {
  // 1. The server owns the fan-out. The client must not try to delete per vendor.
  try await api.post("/v1/account/delete")   // enqueues a durable, retried job

  // 2. Sign in with Apple has to be revoked explicitly, or the link survives deletion
  if let refreshToken = keychain.string(for: .appleRefreshToken) {
    try await api.post("/v1/apple/revoke", body: ["token": refreshToken])
  }

  // 3. Stop the notifications before the account is gone
  await pushService.unregister()             // delete the FCM/APNs token server-side too
  UIApplication.shared.unregisterForRemoteNotifications()

  // 4. Wipe the device. A signOut() that leaves the cache behind is the classic miss.
  try await database.wipe()
  try keychain.removeAll()                   // tokens, refresh tokens, encryption keys
  try FileManager.default.removeItem(at: URL.cachesDirectory)
  UserDefaults.standard.removePersistentDomain(forName: Bundle.main.bundleIdentifier!)

  await analytics.deleteUserData()           // vendor-side erasure, not just opt-out
  session.reset()
}

