// One switch, applied before any SDK initialises, not sprinkled per call site
enum class Audience { CHILD, TEEN, ADULT }

fun configureForAudience(audience: Audience) {
  val childDirected = audience == Audience.CHILD

  MobileAds.setRequestConfiguration(
    RequestConfiguration.Builder()
      .setTagForChildDirectedTreatment(
        if (childDirected) RequestConfiguration.TAG_FOR_CHILD_DIRECTED_TREATMENT_TRUE
        else RequestConfiguration.TAG_FOR_CHILD_DIRECTED_TREATMENT_FALSE
      )
      .setTagForUnderAgeOfConsent(
        if (audience != Audience.ADULT) RequestConfiguration.TAG_FOR_UNDER_AGE_OF_CONSENT_TRUE
        else RequestConfiguration.TAG_FOR_UNDER_AGE_OF_CONSENT_FALSE
      )
      .setMaxAdContentRating(RequestConfiguration.MAX_AD_CONTENT_RATING_G)
      .build()
  )

  // No cross-app identifier at all for a child; the ad id is not a fallback
  FirebaseAnalytics.getInstance(app).apply {
    setAnalyticsCollectionEnabled(!childDirected)
    setConsent(mapOf(ConsentType.AD_PERSONALIZATION to ConsentStatus.DENIED))
  }
}

