// ✅ neutral, asked once, and the birthday itself is never stored
fun onAgeEntered(dateOfBirth: LocalDate): Audience {
  val years = Period.between(dateOfBirth, LocalDate.now()).years
  val audience = when {
    years < 13 -> Audience.CHILD
    years < 18 -> Audience.TEEN
    else -> Audience.ADULT
  }
  prefs.edit().putString("audience_band", audience.name).apply()  // band, not the date
  return audience
}
